void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (Request.QueryString["patientId"] != null)
                    hdnPatientId.Value = Request.QueryString["patientId"];

                if (Request.QueryString["doctorId"] != null)
                    hdnDoctorId.Value = Request.QueryString["doctorId"];

                if (Request.QueryString["name"] != null)
                    hdnPatientName.Value = Request.QueryString["name"];

                // Store patientId in session (same pattern as PatientCommunication)
                if (!string.IsNullOrEmpty(hdnPatientId.Value))
                    Session["ReferralComm_PatientId"] = hdnPatientId.Value;

                if (!string.IsNullOrEmpty(hdnDoctorId.Value))
                    Session["ReferralComm_DoctorId"] = hdnDoctorId.Value;

                lblpatientname.Text = hdnPatientName.Value;
                lblpatientname.ForeColor = System.Drawing.Color.Blue;
            }
        }

handlers.btnsave_Click:
void btnsave_Click(object sender, EventArgs e)
        {
            if (Request.QueryString["patientId"] != null)
                patientId = Convert.ToInt32(Request.QueryString["patientId"]);

            if (Request.QueryString["doctorId"] != null)
                doctorId = Convert.ToInt32(Request.QueryString["doctorId"]);

            try
            {
                if (txtCommunication.InnerText.Trim() == "")
                {
                    lblMessage.Text = "Please Write Communication";
                    lblMessage.ForeColor = System.Drawing.Color.Red;
                    return;
                }

                int appUserId = Convert.ToInt32(HttpContext.Current.Session["appuser"]);
                int practiceId = Convert.ToInt32(HttpContext.Current.Session["practice_id"]);

                string query = @"INSERT INTO ReferralCommunicationLog
                                    (ReferredPatientID, Message, Done_On, Appuser_id, Practice_id, ReferralDoctorID)
                                 VALUES
                                    (@ReferredPatientID, @Message, GETDATE(), @AppUserID, @PracticeID, @ReferralDoctorID)";

                List<SqlParameter> parameters = new List<SqlParameter>
                {
                    new SqlParameter("@ReferredPatientID", patientId),
                    new SqlParameter("@Message",           txtCommunication.InnerText.Trim()),
                    new SqlParameter("@AppUserID",         appUserId),
                    new SqlParameter("@PracticeID",        practiceId),
                    new SqlParameter("@ReferralDoctorID",  doctorId)
                };

                DBHelper dbHelper = new DBHelper();
                dbHelper.ExecuteNonQuery(query, parameters.ToArray(), CommandType.Text);

                lblMessage.Text = "Submitted successfully!";
                lblMessage.ForeColor = System.Drawing.Color.Green;
                txtCommunication.InnerText = "";
            }
            catch (Exception ex)
            {
                lblMessage.Text = "Error: " + ex.Message;
                lblMessage.ForeColor = System.Drawing.Color.Red;
            }
        }

