// event bindings
$('#chkEndComm').on('change', function () {

function saveCommAjax() {
            var comm = $.trim($('textarea[id*="txtCommunication"]').val());
            if (!comm) { showCommMsg('&#9888; Please enter a communication note.', '#b45309', '#fef3c7'); return; }

            var selectedIds = $('#ddlPendingStatus').val() || [];
            if (!Array.isArray(selectedIds)) selectedIds = [selectedIds];
            var DueAction = $('#chkDueAction').is(':checked');
            var EndComm = $('#chkEndComm').is(':checked');
            var followUpDate = $('#<%= txtfollowUpDate.ClientID %>').val() || null;

            if (followUpDate && selectedIds.length === 0) {
                showCommMsg('&#9888; Please assign a user when follow-up date is set.', '#b45309', '#fef3c7');
                return;
            }

            var btn = $('#btnSaveAjax');
            btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Saving&hellip;');

            $.ajax({
                type: 'POST', url: 'ReferralCommunicationLogs.aspx/SaveCommunication',
                contentType: 'application/json; charset=utf-8', dataType: 'json',
                data: JSON.stringify({
                    note: comm,
                    ddlPendingStatus: selectedIds.map(Number),
                    DueAction: DueAction,
                    EndComm: EndComm,
                    followUpDate: followUpDate
                }),
                success: function (res) {
                    if (res.d === '1') {
                        $('textarea[id*="txtCommunication"]').val('');
                        $('#ddlPendingStatus').val(null).trigger('change');
                        $('#chkDueAction').prop('checked', false).prop('disabled', false);
                        $('#chkEndComm').prop('checked', false);
                        $('#<%= txtfollowUpDate.ClientID %>').val('');
                        $('#followUpDateProxy').val('');
                        $('#followupSetMsg').hide();
                        $('#chipsArea').empty();
                        showCommMsg('&#10003; Communication saved!', '#065f46', '#d1fae5');
                        GetReport();
                    } else {
                        showCommMsg('&#10007; Failed to save. Please try again.', '#991b1b', '#fee2e2');
                    }
                },
                error: function (xhr) {
                    showCommMsg('&#10007; Server error: ' + (xhr.statusText || 'Unknown'), '#991b1b', '#fee2e2');
                },
                complete: function () {
                    btn.prop('disabled', false).html('<i class="fa fa-paper-plane"></i> Send Note');
                }
            });
        }
